function deriveProtocolSchemas() {
	const excluded = new Set(EXCLUDED_SCHEMA_EXPORTS);
	for (const name of excluded) if (!Object.hasOwn(schemaSources, name)) throw new Error(`Unknown excluded protocol schema export: ${name}`);
	const names = Object.keys(schemaSources).filter((name) => name.endsWith("Schema")).toSorted();
	const entries = [];
	for (const name of names) if (!excluded.has(name)) entries.push([name.slice(0, -6), schemaSources[name]]);
	return Object.fromEntries(entries);
}
